  `acknowledgement_notes` text,
  `review_due_at` datetime DEFAULT NULL,
  `reminder_count` int NOT NULL DEFAULT '0',
  `last_reminder_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `result_id` (`result_id`),
  KEY `patient_id` (`patient_id`),
